 Outcome<std::optional<MilitaryTacticLearningObservation>> value(const StableId& actor,const StableId& tactic,Integer tick,const StableId& before)const{
  if(!qualified||(actor=="student"&&!student_known))return {true,std::nullopt,{}};MilitaryTacticLearningObservation p;p.source_identity=c.state().identity;p.actor_id=actor;p.tactic_id=tactic;p.acquisition_fact_id="military_tactic:2";p.source_fact_id="initial_teacher";p.initial_grant_id="initial_teacher";p.source_kind=MilitaryTacticLearningSourceKind::authored_initial;p.acquired_tick=0;p.observed_tick=tick;p.before_fact_id=before;return {true,p,{}};
 }
